  for p in sorted(paths):
   i=zipfile.ZipInfo(str(p.relative_to(R)));i.date_time=(2026,10,11,0,0,0);i.compress_type=zipfile.ZIP_DEFLATED;z.writestr(i,p.read_bytes())
